INSERT INTO `v1_0d733b39c1b4f200ecde636d692b961d65fd6243bd3e5ac7dc3edea76b5ec890` VALUES (6, 0, "", 6010, "vo_minigame_1013_top_talk_6_001", 0, "", 21, "vo_minigame_1013", "", "");
INSERT INTO `v1_0d733b39c1b4f200ecde636d692b961d65fd6243bd3e5ac7dc3edea76b5ec890` VALUES (6, 6, 0.8, 6011, "マコトさん？\nどうかしましたか？\n何やら不穏な気配を\n感じ取ったのですが", 1, 0, 11, 129911, 0, 0);
INSERT INTO `v1_0d733b39c1b4f200ecde636d692b961d65fd6243bd3e5ac7dc3edea76b5ec890` VALUES (6, "", "", 6012, "", "", "", 91, 0, "", "");
