INSERT INTO `v1_0d733b39c1b4f200ecde636d692b961d65fd6243bd3e5ac7dc3edea76b5ec890` VALUES (6, 0, "", 6014, "drama_talk_surprise_in_shy", "drama_talk_surprise_loop_shy", 0.2, 3, 129811, 1, "");
INSERT INTO `v1_0d733b39c1b4f200ecde636d692b961d65fd6243bd3e5ac7dc3edea76b5ec890` VALUES (6, 0, "", 6015, "vo_minigame_1013_top_talk_6_002", 0, "", 21, "vo_minigame_1013", "", "");
INSERT INTO `v1_0d733b39c1b4f200ecde636d692b961d65fd6243bd3e5ac7dc3edea76b5ec890` VALUES (6, 9, 0.3, 6016, "いやいや何でもない！\nあたしは別に変なこと\n考えてないからな！\nそれより訓練だっ！", 1, 0, 11, 129811, 0, 0);
INSERT INTO `v1_0d733b39c1b4f200ecde636d692b961d65fd6243bd3e5ac7dc3edea76b5ec890` VALUES (6, "", "", 6017, "", "", "", 91, 0, "", "");
